          "You are loyal in a way that does not need to be tested. Cancer would not leave you for a better offer and Taurus would not even look at the offer.",
          "You are good to each other on bad days. Taurus stays solid when Cancer is spiralling, and Cancer brings softness when Taurus is hard on themselves.",
