          "Taurus can be possessive about money and things, and Cancer can be possessive about people. The fight over who the visiting family should stay with, or whose friends come first, gets personal quickly.",
          "Both of you hold grudges. A harsh word at a dinner party turns into a six-month background hum, with Cancer sulking and Taurus refusing to apologise.",
