          "Both of you keep feelings to yourselves. Virgo analyses them privately and Taurus sits on them, so weeks can pass with an issue unspoken.",
          "When it goes missing, Virgo criticises and Taurus digs in. One of you says you always do this, the other says nothing, and the room goes cold."
