          "Virgo notices what is off and says so. Taurus hears a list of faults when it was meant as help, and answers with silence or a flat no.",
          "Taurus decides slowly and sticks to it. Virgo keeps refining the plan and revisiting the question, and Taurus gets irritated at being asked a fourth time.",
          "Texts are practical and fond. Did you remember the bin, there's soup in the fridge, and the affection is hidden in the logistics.",
