          "You are good with money together. Taurus saves and enjoys, Virgo tracks and trims, and the household accounts are rarely a source of anxiety.",
          "You look after each other's bodies. Virgo notices when Taurus is run down and Taurus makes sure Virgo eats properly, so you tend to be healthier as a pair.",
          "You are loyal in a plain, daily way. Neither of you needs grand declarations, and both of you would be quietly horrified by the idea of cheating.",
          "You make a home that works. The garden grows, the kitchen is organised, and guests notice how calm it feels."
