          "Hold a weekly ten-minute check-in with one question each: what bothered you, what did you like. It stops the slow build-up of unsaid things.",
          "Plan something that is useless on purpose. A day trip, a long lunch or a concert with no productive outcome, because neither of you does it by default.",
