          "Neither of you says everything. Each keeps back a card, a thought, a hurt. The other senses it and fills in the story, and the story is usually darker than the truth.",
          "Texting is short, loaded and sometimes deliberately ambiguous. Scorpio sends a period and Cancer spends the afternoon decoding it. Say what you mean in words, not punctuation.",
          "Arguments are slow, serious and long-memoried. Neither of you forgets. A fight in June is still in the file in December, so apologize fully, not halfway."
