          "You build a home and savings steadily and quietly, with a clear understanding of what stays private.",
          "You protect the family and the inner circle. Outsiders get a polite face and insiders get everything.",
          "You heal each other. Both of you carry old hurts, and in this relationship they are met without a joke or a fix. Many people count this as the first time they felt safe."
