          "Scorpio gives Libra depth, a reason to stop floating on the surface. Libra gives Scorpio ease, a reason to loosen their grip and enjoy something. Each of you becomes more complete in the other's company.",
          "When trust is established, you are fiercely loyal. Libra's commitment to fairness and Scorpio's commitment to the bond mean that neither of you quits easily. You stay through the hard parts.",
