          "The catch is that neither of you likes heavy emotion. When something painful comes up, Libra smooths it and Sagittarius jokes it away. You have a lovely time and the sore point stays exactly where it was.",
          "Sagittarius can say careless things and not notice the impact, and Libra will take the hit politely and carry it quietly. A week later Libra is cooler and Sagittarius cannot work out why. The explanation is usually a sentence that took half a second to say.",
          "What you need is to stay in the uncomfortable conversation five minutes longer than feels natural. Sit still, name the feeling, do not make a joke. It will feel awkward, and it is what turns a great time into a lasting bond."
