          "Libra brings balance and listens to every side. Sagittarius brings conviction and the big picture. Between you, the argument is lively and rarely bitter, and you often change each other's minds.",
          "The tension comes from tact. Sagittarius says the plain, blunt thing and Libra winces, because Libra would have found three softer ways to say it. Sagittarius thinks Libra is being fake, Libra thinks Sagittarius is being careless.",
          "Decisions can float. Libra cannot choose and Sagittarius cannot be bothered to, so the trip is discussed enthusiastically and booked three weeks late. Someone has to push the button.",
          "Texting is warm and loose. Neither of you is strict about response time, and neither keeps score. Plans are made by message and then renegotiated by message."
