          "Libra needs harmony in the room and will swallow a lot to keep it. You say it is fine, you smile, and three days later the real complaint comes out sideways. Capricorn, who takes words at face value, is blindsided and feels lied to.",
          "Capricorn needs to know the relationship is solid before relaxing, and hates being asked to perform affection on demand. When Libra pushes for a romantic gesture, Capricorn hears a test they were never given the syllabus for.",
