          "Text exchanges expose it fast. Libra sends a paragraph with two emojis and a question mark, and Capricorn replies with one line that answers only the question mark. Libra reads the short reply as cold. It was just efficient.",
          "Arguments go badly in a specific way. Capricorn states the problem as a flat fact, Libra hears an accusation, and replies with a diplomatic reframe that makes Capricorn feel handled.",
