          "Capricorn can use sex as a way of not talking. Libra wants the talking first, the romance, the feeling of being chosen. Settle that order once and the rest goes well.",
          "Over time the physical side improves with the relationship rather than despite it. You two are better at month eighteen than at week three, which is the opposite of most couples."
