          "Libra softens Capricorn's reputation. Capricorn is the person who is respected, Libra is the one who is liked, and standing next to Libra makes Capricorn approachable at work dinners.",
          "Capricorn gives Libra a spine in decisions. When Libra has been flipping between two options for a week, Capricorn can ask one practical question and the choice is made.",
          "Both of you care how things look and what they cost, so a home you build together is tasteful and not wasteful. Nobody ends up in debt for a sofa.",
