          "Libra needs to feel chosen, repeatedly and visibly. Aquarius considers the choice made already, as a settled fact, and thinks repeating it is redundant.",
          "Neither of you is good at the raw end of emotion. When one of you cries, the other says something reasonable, and the reasonable thing is exactly wrong.",
          "What helps is naming it. Aquarius says I need Thursday to myself and I am coming back, Libra says I need you to tell me tonight that you are glad to be with me, and both of you do what was asked without taking it as an insult."
