          "Build in a touch ritual that does not depend on mood. A hug at the door, a hand held in the car. Libra gets the reassurance on schedule and Aquarius does not have to feel it as pressure.",
          "Libra, practise asking for what you want on the first request, not the third hint. Aquarius will do almost anything if told clearly and will do nothing if left to guess.",
