          "Pisces says I just have a feeling about it, and Capricorn wants evidence. Capricorn says here is the budget, and Pisces hears a wall. Neither of you is wrong, but you have to learn to meet in the middle: Pisces gives one concrete example, Capricorn listens past the numbers.",
          "Texting suits you in different ways. Capricorn is brief and dependable. Pisces sends longer messages with songs and half-thoughts attached. Capricorn can reply with one warm, specific line and make Pisces's whole day.",
